def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    def decorator(func):
        cache = {}
        hits = misses = 0
        lock = threading.RLock()

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            k = _make_key(args, kwargs, typed)
            with lock:
                now = timer()
                try:
                    value, last_accessed = cache.pop(k)
                    if now - last_accessed <= ttl:
                        hits += 1
                        cache[k] = (value, now)
                        return value
                    misses += 1
                except KeyError:
                    pass
            value = func(*args, **kwargs)
            with lock:
                cache[k] = (value, now)
            return value

        def _make_key(args, kwargs, typed):
            if not args and not kwargs:
                return 0
            if typed:
                return repr(args), repr(kwargs)
            return repr((args, kwargs))

        @property
        def ratio(self):
            return hits / (hits + misses)

        wrapper.cache_info = cache.info
        wrapper.cache_clear = cache.clear
        wrapper.cache_ttl = ttl
        wrapper.ratio = ratio
        wrapper.hits = hits
        wrapper.misses = misses

        return wrapper

    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = []
        hits = misses = 0
        lock = Lock()
        root = []
        root[:] = [root, root, None, None]
        root.prev = root.next = root
        dispose = []

        if typed:
            def key(args, kwargs):
                return (func, args, frozenset(kwargs.items()))
        else:
            def key(args, kwargs):
                return (func, args, frozenset(kwargs.items()))

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            k = key(args, kwargs)
            with lock:
                for link in cache:
                    if link.expired():
                        dispose.append(link)
                    elif k == link.key:
                        root.move_to_end(link)
                        return link.value
                result = func(*args, **kwargs)
                misses += 1
                if len(cache) < maxsize:
                    link = [root, root, k, result]
                    cache.append(link)
                    root.insert_after(link)
                    return result
                # handle maxsize
                dispose.append(root.prev)
                link = [root, root, k, result]
                cache[-1] = link
                root.insert_after(link)
                return result

        def info():
            with lock:
                return {"hits": hits, "misses": misses, "maxsize": maxsize}

        def stats():
            with lock:
                return [
                    (link.key, link.value, link.expired())
                    for link in cache
                    if not link.expired()
                ]

        wrapper.hits = property(lambda: hits)
        wrapper.misses = property(lambda: misses)
        wrapper.maxsize = property(lambda: maxsize)
        wrapper.info = info
        wrapper.stats = stats
        return update_wrapper(wrapper, func)

    return decorator

