def lfu_cache(func, maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    # Define a custom cache class to implement the LFU algorithm
    class LFUCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = {}
            self.frequencies = {}
            self.currsize = 0

        def get(self, args, kwargs):
            key = self.make_key(args, kwargs)
            try:
                value = self.cache[key]
                self.frequencies[key] += 1
                return value
            except KeyError:
                msg = "key not found in cache"
                raise KeyError(msg)

        def put(self, args, kwargs, value):
            key = self.make_key(args, kwargs)
            value2 = self.cache.get(key)

            # If key is already in the cache
            if value2 is not None:
                # Replace the existing item with the new value
                self.cache[key] = value
                self.frequencies[key] += 1
                return

            # If the cache is at capacity, remove the least frequently used item
            if self.currsize >= self.maxsize:
                for k, f in self.frequencies.items():
                    if f == min(self.frequencies.values()):
                        del self.cache[k]
                        del self.frequencies[k]
                        break

            self.cache[key] = value
            self.frequencies[key] = 1
            self.currsize += 1

        def make_key(self, args, kwargs):
            # Make a key from the args and kwargs
            key = []
            for a in args:
                key.append(a)
            for k, v in kwargs.items():
                key.append((k, v))
            if self.typed:
                key = tuple(key)
            else:
                key = tuple([str(k) for k in key])
            return key

    # Return the wrapped function
    def decorator(*args, **kwargs):
        # Check if the cache is full
        if cache.currsize >= cache.maxsize:
            raise Exception("Cache is full")
        # Get the value from the cache
        value = cache.get(args, kwargs)
        # If the value is not in the cache, call the function and put it in the cache
        if value is None:
            value = func(*args, **kwargs)
            cache.put(args, kwargs, value)
        return value

    # Create the cache and wrap the function
    cache = LFUCache(maxsize, typed)
    return decorator

