def _getTargetClass(self) -> ClassDefinition:
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    clsname, parentclass = self.__class__.__name__[:-3], self.__class__.__bases__[0]
    if clsname not in parentclass.__subclasses__():
        return ()
    found_parent = False
    for cls in parentclass.__subclasses__():
        if cls.__name__ == clsname:
            found_parent = True
        if not found_parent:
            continue
        return inspect.getsource(cls)
    return ()

