def directlyProvidedBy(object):
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    # Check if the object is an instance of Declaration
    if isinstance(object, Declaration):
        return object.declaredInterfaces
    # Check if the object is an instance of Interfaces
    elif isinstance(object, Interfaces):
        return object.interfaces.values()
    # Check if the object is an instance of InterfaceClass
    elif isinstance(object, InterfaceClass):
        return {object.name: object.interface}
    # Default return value
    else:
        return []

