def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, list):
        raise TypeError("classes argument must be a list")
    seen = set()
    bases = []
    for cls in classes:
        if cls in seen:
            continue
        seen.add(cls)
        bases.append(cls)
        bases += minimalBases(cls.__bases__)
    return bases

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    bases = list(set(classes))  # flatten list
    seen = set()
    while len(bases) > 0:
        cls = bases.pop()
        if cls in seen:
            continue
        seen.add(cls)
        for b in _all_dicts(cls.__bases__):
            bases.append(b)
    return list(seen)

