        #TODO: Consider type _InterfaceType
        return isinstance(key, type)

    def _is_function(key):
        #TODO: Consider type _InterfaceFunction
        return hasattr(key, "__call__")

    names = []
    descriptions = []
    for key, value in self.__dict__.items():
        if _is_var(key) or _is_class(key) or _is_function(key):
            if all or value.__doc__:
                names.append(key)
                descriptions.append(value.__doc__ or "")

    return names, descriptions

