    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if isinstance(sequence, InterfaceClass):
        output.append(sequence)
    elif isinstance(sequence, zope.interface.declarations.Implements):
        output.append(sequence)
    elif isinstance(sequence, tuple):
        for v in sequence:
            _normalizeargs(v, output)
    elif isinstance(sequence, tuple):
        for v in sequence:
            _normalizeargs(v, output)
    else:
        raise RuntimeError("Invalid argument `sequence`: expected Declarion or tuple")

