def difference(d1, d2, level=-1):
    # dictionary to store the difference
    diff = {}
    if level == -1:
        # infinite recursion
        for key, val1 in d1.items():
            if key not in d2 or val1 != d2[key]:
                diff[key] = val1
        return diff
    else:
        # finite recursion
        for key, val1 in d1.items():
            if key not in d2 or (level > 0 and isinstance(val1, dict)):
                diff[key] = val1
            elif level > 0 and isinstance(val1, dict):
                diff[key] = difference(val1, d2[key], level-1)
        return diff

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, tuple):
        raise ValueError("coord must be a tuple")
    if not len(coord) == 2:
        raise ValueError("coord must have length 2")
    if not np.isscalar(weight):
        raise ValueError("weight must be a scalar")

    x, y = coord
    if not np.isclose(x, int(x)):
        raise ValueError("x must be an integer")
    if not np.isclose(y, int(y)):
        raise ValueError("y must be an integer")

    if x < 0 or x >= self.size_x:
        return
    if y < 0 or y >= self.size_y:
        return

    self.array[y, x] += weight

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective regular expression. The error contains as message the list of all errors which occurred in the labels. Each element of the list is a dictionary with one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    messages = []
    for key, value in labels.items():
        if not _validate_label_key(key):
            message = "['{}']: Label key '{}' does not match the regex {}".format(
                key, key, _LABEL_KEY_REGEX
            )
            messages.append({"key": key, "msg": message})
        if not _validate_label_value(value):
            message = "Key '{}': expected string or bytes-like object".format(
                key
            )
            messages.append({"key": key, "msg": message})
    if messages:
        raise ValidationError(messages)

def _validate_labels(labels):
    errors = []
    for label_key, label_value in labels.items():
        if not isinstance(label_key, str):
            errors.append({"key": str(label_key),
                           "value": "expected string or bytes-like object"})
        if not isinstance(label_value, (str, list)):
            errors.append({"value": str(label_value),
                           "value": "expected string or bytes-like object"})
        if not re.fullmatch(LABEL_KEY_REGEX, label_key):
            errors.append({"key": label_key,
                           "value": f"Label key '{label_key}' does not match the regex {LABEL_KEY_REGEX}"})
        if isinstance(label_value, list):
            for val in label_value:
                if not re.fullmatch(LABEL_VALUE_REGEX, val):
                    errors.append({"value": val,
                                   "value": f"Label value '{val}' does not match the regex {LABEL_VALUE_REGEX}"})
    if errors:
        raise ValidationError(messages=errors)

def _validate_labels(labels):
    messages = []
    regex = r"[a-zA-Z_][a-zA-Z0-9_]{0,50}"
    for key, value in labels.items():
        if not isinstance(key, str):
            messages.append({key: "Expected string or bytes-like object"})
        elif not re.match(regex, key):
            messages.append({key: "Label key '%s' does not match the regex '%s'" % (key, regex)})
        if not isinstance(value, (str, list)):
            messages.append({value: "Expected string or list"})
    if messages:
        raise ValidationError(messages)

