def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Generate part of a default observer_schema from part of a Kubernetes resource

    Args:
        manifest_dict (dict): Partial Kubernetes resource
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer_schema of a Kubernetes resource. Defaults to False.

    Returns:
        dict: Generated partial observer_schema
    """
    observer_schema = {}
    for key, value in manifest_dict.items():
        if isinstance(value, (list, dict)):
            observer_schema[key] = generate_default_observer_schema_dict(
                value, first_level=False
            )
        else:
            observer_schema[key] = None
    if first_level:
        for key in ["metadata", "spec"]:
            if key in manifest_dict:
                observer_schema[key] = manifest_dict[key]
    return observer_schema

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate a default ``observer_schema`` from a Kubernetes resource.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the complete observer schema of a Kubernetes resource

    Returns:
        dict: Generated default observer_schema

    """
    if first_level:
        observer_schema = {
            "apiVersion": manifest_dict["apiVersion"],
            "kind": manifest_dict["kind"],
            "metadata": {
                "name": manifest_dict["metadata"]["name"],
                "namespace": manifest_dict["metadata"]["namespace"],
            },
            "spec": manifest_dict["spec"],
        }
    else:
        observer_schema = {}
        for key, value in manifest_dict.items():
            if isinstance(value, dict):
                observer_schema.update({key: generate_default_observer_schema_dict(value)})
            elif isinstance(value, list):
                observer_schema.update({key: generate_default_observer_schema_list(value)})
            else:
                observer_schema.update({key: None})

    return observer_schema

def update_last_applied_manifest_list_from_resp(
        last_applied_manifest, observer_schema, response
    ):
        if isinstance(response, list):
            for i, obs_data in enumerate(observer_schema):
                if obs_data is None:
                    continue
                if i < len(response):
                    resp_data = response[i]
                    last_resp_data = (
                        last_applied_manifest[i]
                        if i < len(last_applied_manifest)
                        else None
                    )
                    update_last_applied_manifest_dict_from_resp(
                        last_resp_data, obs_data, resp_data
                    )
                else:
                    last_applied_manifest.append(None)

        # elif both response and last_applied_manifest are not lists
        else:
            raise ValueError(
                "Response and last_applied_manifest both must be lists"
            )

        return last_applied_manifest

    def update_last_applied_manifest_dict_from_resp(
        last_applied_manifest, observer_schema, response
    ):
        if isinstance(last_applied_manifest, dict):
            for k, v in last_applied_manifest.items():
                if k in response:
                    v = response[k]
                elif k in observer_schema:
                    v = observer_schema[k]
                elif k in last_applied_manifest:
                    v = last_applied_manifest[k]
                last_applied_manifest[k] = v

        # elif both response and last_applied_manifest are not dict
        else:
            raise ValueError(
                "Response and last_applied_manifest both must be dicts"
            )

        return last_applied_manifest

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this function is called 
    recursively to update a partial ``last_applied_manifest`` from a partial Kubernetes response.
    It will go through all observed fields and initialize their value in `last_applied_manifest` if they are not yet present.
    """
    for i, field in enumerate(observer_schema):
        field_name = field["name"]
        try:
            field_value = response[i]
            # if the field is not present in last_applied_manifest, initialize it
            if field_name not in last_applied_manifest[i]:
                last_applied_manifest[i][field_name] = None
            # if the field has a value, recurse into it
            if field_value is not None:
                last_applied_manifest[i][field_name] = update_last_applied_manifest_from_resp(
                    last_applied_manifest[i][field_name], field["children"], field_value
                )
        except IndexError:
            # if the field is not present in the response, set its value to None
            last_applied_manifest[i][field_name] = None
        except KeyError:
            # if the field is not present in the response, set its value to None
            last_applied_manifest[i][field_name] = None
    return last_applied_manifest[i]

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response"""
    for i, (man_item, schema_item) in enumerate(zip(last_applied_manifest, observer_schema)):
        if isinstance(man_item, dict):
            response_item = response[i]
            if not isinstance(response_item, dict):
                raise ValueError("Response item is not a dict.")
            update_last_applied_manifest_dict_from_resp(man_item, schema_item, response_item)
        elif isinstance(man_item, list):
            response_item = response[i]
            if not isinstance(response_item, list):
                raise ValueError("Response item is not a list.")
            update_last_applied_manifest_list_from_resp(man_item, schema_item, response_item)
        else:
            raise ValueError("Manifest item is not a dict or a list.")

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field in observer_schema:
        try:
            last_applied_manifest[field]
        except KeyError:
            last_applied_manifest[field] = response[field]

