def format(sql, params):
    if isinstance(params, dict):
        params = {f"@{name}": value for name, value in params.items()}
    else:
        params = [f"@{i+1}": value for i, value in enumerate(params)]
    return sql.format(**params), params

def format(self, sql, params):
    index = 0
    sql = sql.replace('%s', '?')
    bound_params = []
    if not isinstance(params, dict):
        params = dict(zip(range(len(params)), params))
    for param in sql:
        if param.endswith('?') and param.startswith('='):
            value = params[param.strip('= %')]
            bound_params.append(value)
            sql = sql.replace(param, '?', 1)
    return sql, bound_params

def formatmany(sql, many_params):
    formatted_sql = sql
    params_list = []

    for params in many_params:
        if not isinstance(params, (dict, list)):
            raise ValueError("Params must be a dictionary or a list")

        if isinstance(params, dict):
            params = list(params.values())

        formatted_sql = formatted_sql + ":%d"
        params_list.append(params)

    return formatted_sql, params_list

def formatmany(sql, many_params):
    formatted_sql = sql
    out_params = []
    for params in many_params:
        if isinstance(params, Mapping):
            out_params.append(params)
            for k, v in params.items():
                formatted_sql = formatted_sql.replace("%s", f"{v}")
        elif isinstance(params, Sequence):
            out_params.append(params)
            for i, v in enumerate(params):
                formatted_sql = formatted_sql.replace(f"{i+1}", f"{v}")
        else:
            raise ValueError("Invalid params type")
    return (formatted_sql, out_params)

def formatmany(self, sql, many_params):
    out_params = []
    for params in many_params:
        out_params.append(tuple(params.values()))
    return sql, out_params

def formatmany(sql, many_params):
    out_params = []
    for params in many_params:
        if isinstance(params, dict):
            out_params.append({k: f"'{v}'" if isinstance(v, str) else v for k, v in params.items()})
        else:
            out_params.append([f"'{v}'" if isinstance(v, str) else v for v in params])
    return sql, out_params

def validate(path):
    # Check if path is valid
    if not path:
        return False

    # Check if path represents a valid file
    if not os.path.isfile(path):
        raise errors.NotAFileError('Value (%s) is not a file' % path)

    # Check if file is a supported media type
    if not is_supported_media_type(path):
        return False

    # Check if file is a valid OCFL object
    if not is_valid_ocfl_object(path):
        return False

    return True

def validate(path: str):
    if not path:
        raise ValueError("path cannot be empty")
    if not os.path.exists(path):
        raise PathExistsError("path does not exist")
    if not os.path.isdir(path):
        raise NotADirectoryError("path is not a directory")
    return True

def validate(self, path):
    if not os.path.exists(path):
        raise errors.NotFoundError('Path (%s) does not exist' % path)

    if not path.endswith('/'):
        path += '/'

    if not os.path.isdir(path):
        raise errors.NotADirectoryError('Path (%s) is not a directory' % path)

    if not os.access(path, os.R_OK):
        raise errors.ReadAccessDeniedError('Read access to path (%s) is denied' % path)

    return True

def validate(path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.

    :param path: The path to validate.
    :type path: :class:`str <python:str>`

    """
    if not path:
        raise ValueError('path (%s) was empty' % path)

    path = path.rstrip(os.sep)

    if os.path.isdir(path):
        try:
            root_object = RootObject(path, load=False, allow_non_claimed=False)
        except pyfs.errors.InvalidClaimError:
            return False
    else:
        try:
            root_object = RootObject(os.path.split(path)[0], load=False, allow_non_claimed=False)
        except pyfs.errors.InvalidClaimError:
            return False
        else:
            if not root_object.is_object_root():
                return False

    if root_object.type != 'http://www.w3.org/ns/pim/space#Context' and root_object.type != 'http://www.w3.org/ns/ldp#BasicContainer':
        return False

    if not root_object.label:
        return False

    if not root_object.slug:
        return False

    if not root_object.created_by:
        return False

    if not root_object.created:
        return False

    if not root_object.state:
        return False

    if not root_object.state.is_in(('initialized', 'locked', 'validated', 'broken')):
        return False

    if not root_object.state == 'initialized':
        if not root_object.locked_by:
            return False

        if not root_object.locked:
            return False

    if root_object.base_uri:
        if not root_object.base_uri.startswith('http://') and not root_object.base_uri.startswith('https://'):
            return False

    if not root_object.storage_uri and not root_object.storage_domain:
        return False

    if root_object.storage_domain and not root_object.update_list:
        return False

    if root_object.manifest_resource:
        if not root_object.manifest_resource.version:
            return False

        if not root_object.manifest_resource.filesystem_path:
            return False

        if not root_object.manifest_resource.full_uri:
            return False

        if not root_object.manifest_resource.size:
            return False

        if not root_object.manifest_resource.format:
            return False

        if not root_object.manifest_resource.mimetype:
            return False

        if root_object.manifest_resource.mimetype and not root_object.manifest_resource.mimetype.startswith('text/plain'):
            return False

    return True

