def validate(self, inventory, extract_spec_version=False):
    if extract_spec_version:
        if 'type' in inventory:
            if inventory['type'] in self.supported_types:
                spec_version = self.supported_types[inventory['type']]
                inventory['override_version'] = spec_version
            else:
                raise ValueError("Unsupported type input: {}".format(inventory['type']))

    if 'override_version' not in inventory:
        inventory['override_version'] = self.spec_version

    if not isinstance(inventory, dict):
        raise ValueError("Invalid input inventory: {}".format(inventory))

    self._verify_fields(inventory)
    self._verify_items(inventory)
