def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    try:
        if not isinstance(inventory, dict):
            raise TypeError("Invalid inventory data type")
        if not inventory:
            raise ValueError("Inventory is empty")
        if extract_spec_version:
            if "type" in inventory:
                spec_version = inventory["type"]
            else:
                raise KeyError("Missing type field in inventory")
        else:
            spec_version = self.spec_version
        self._validate_type(spec_version)
        self._validate_required_fields(spec_version, inventory)
        self._validate_schema_constraints(spec_version, inventory)
        return inventory
    except (TypeError, ValueError, KeyError) as e:
        raise e

