    self._validate_inventory_resources(inventory, spec_version)

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    for manifest_file in manifest_files:
        with open(manifest_file, "r") as f:
            digests_present = re.findall(r"\b[a-fA-F0-9]{64}\b", f.read())
            for digest in digests_present:
                if digest not in digests_used:
                    raise ValueError(f"The digest {digest} in the manifest file {manifest_file} is not used by the application.")
        if not digests_present:
            raise ValueError(f"No digests found in the manifest file {manifest_file}.")

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    for manifest in manifest_files:
        if not manifest.endswith('.xml'):
            continue

        manifest_file = self.build_dir(os.path.join('manifest', manifest))
        if not os.path.exists(manifest_file):
            continue

        with open(manifest_file, 'r') as f:
            manifest_text = f.read()

        manifest_lines = manifest_text.split('\n')
        for line in manifest_lines:
            if 'android-ls' in line:
                digest = line.split(';')[1][1:]
                if digest not in digests_used:
                    raise ValueError('DIGEST_NOT_FOUND: {}'.format(digest))

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    manifest_files = self.check_file_list(manifest_files)
    digests_used = self.check_list_of_strings(digests_used)
    for digest in digests_used:
        if not any(digest in file for file in manifest_files):
            raise KeyError(f"Digest {digest} is not found in the manifest files")
    for file in manifest_files:
        if not any(digest in file for digest in digests_used):
            raise KeyError(f"Digest {digest} is not used in the manifest files")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Check that prior is not None
    if prior is None:
        raise ValueError("Prior inventory is None")

    # Check that prior is an InventoryValidator object
    if not isinstance(prior, InventoryValidator):
        raise ValueError("Prior inventory is not an InventoryValidator object")

    # Check that prior and self have the same number of items
    if len(self.inventory) != len(prior.inventory):
        raise ValueError("Prior and current inventories have different number of items")

    # Check that prior and self have the same items
    for idx, item in enumerate(self.inventory):
        if item.id != prior.inventory[idx].id:
            raise ValueError("Prior and current inventories have different items")

        # Check that the quantity of the item is non-negative
        if item.quantity < 0:
            raise ValueError("Quantity of item {} is negative in current inventory".format(item.name))

        # Check that the quantity of the item is less than or equal to the prior quantity
        if item.quantity > prior.inventory[idx].quantity:
            raise ValueError("Current inventory has more quantity of item {} than the prior inventory".format(item.name))

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError('prior is not an InventoryValidator object')

    if self.currency != prior.currency:
        raise ValueError('currencies do not match')

    if self.delivery_dates != prior.delivery_dates:
        raise ValueError('delivery dates do not match')

    if self.product_ids != prior.product_ids:
        raise ValueError('product ids do not match')

    for product in self.product_list:
        if not prior.has_product(product):
            raise ValueError('prior inventory does not have product: {}'.format(product))

        if prior.get_product_stock(product) < self.get_product_stock(product):
            raise ValueError('inventory before increment is higher than inventory after increment')

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Check that prior and self have same length
        if len(self.inventory) != len(prior.inventory):
            raise ValueError("Input prior and self must have the same length")

        # Check that inventory items in both self and prior are in the same order
        for i, item_i in enumerate(self.inventory):
            item_j = prior.inventory[i]
            if item_i is not item_j:
                raise ValueError("Input prior and self must have the same inventory items in the same order")

        # Check that prior production rate is less than or equal to self production rate
        for i, item_i in enumerate(self.inventory):
            item_j = prior.inventory[i]
            if item_i.production_rate > item_j.production_rate:
                raise ValueError("Input prior production rate must be less than or equal to self production rate")

        # Check that prior processing time is less than or equal to self processing time
        for i, item_i in enumerate(self.inventory):
            item_j = prior.inventory[i]
            if item_i.processing_time > item_j.processing_time:
                raise ValueError("Input prior processing time must be less than or equal to self processing time")

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Check if prior is of the same type as self
    if not isinstance(prior, InventoryValidator):
        raise TypeError("expected prior to be of type InventoryValidator, but got {}" .format(type(prior)))

    # Check if prior has the same number of items as self
    if len(prior.items) != len(self.items):
        raise ValueError("prior and self have different number of items")

    # Check if prior has the same number of categories as self
    if len(prior.categories) != len(self.categories):
        raise ValueError("prior and self have different number of categories")

    # Check if prior has the same inventory parameters as self
    if prior.inventory_parameters != self.inventory_parameters:
        raise ValueError("prior and self have different inventory parameters")

    # Check if prior has the same cost matrix as self
    if prior.cost_matrix != self.cost_matrix:
        raise ValueError("prior and self have different cost matrices")

    # Check if prior has the same delayed increase/decrease parameters as self
    if prior.delayed_increase_params != self.delayed_increase_params or prior.delayed_decrease_params != self.delayed_decrease_params:
        raise ValueError("prior and self have different delayed increase/decrease parameters")

    # Check if prior has the same historical sales/failure data as self
    if len(prior.historical_sales) != len(self.historical_sales):
        raise ValueError("prior and self have different number of historical sales")

    if len(prior.historical_failures) != len(self.historical_failures):
        raise ValueError("prior and self have different number of historical failures")

    # Check if prior has the same initial inventory level and initial sales level as self
    if prior.initial_inventory_level != self.initial_inventory_level or prior.initial_sales_level != self.initial_sales_level:
