def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Check that both objects have the same kind of inventory
    if self.kind != prior.kind:
        return False

    # Check that both inventories have the same layout
    if self.layout != prior.layout:
        return False

    # Check that both inventories have the same party
    if self.party != prior.party:
        return False

    # Check that the versions are valid
    if self.version >= prior.version:
        return False

    # Check that the quantities are equal
    for sku in self.quantities:
        if sku not in prior.quantities:
            return False
        if self.quantities[sku] != prior.quantities[sku]:
            return False

    # Check that the receipts are equal
    for sku in self.receipts:
        if sku not in prior.receipts:
            return False
        if self.receipts[sku] != prior.receipts[sku]:
            return False

    # Check that the vouchers are equal
    for sku in self.vouchers:
        if sku not in prior.vouchers:
            return False
        if self.vouchers[sku] != prior.vouchers[sku]:
            return False

    # Check that the signatures are equal
    for sku in self.signatures:
        if sku not in prior.signatures:
            return False
        if self.signatures[sku] != prior.signatures[sku]:
            return False

    # If all checks pass, return True
    return True

def get_logical_path_map(inventory, version):
    logical_path_map = {}
    for path in inventory.walk(version):
        if path.action == "add":
            content_files = set()
            if path.content_path is not None:
                content_files = inventory.get_content_files(path.content_path)
            else:
                content_files = set()
            logical_path_map[path.logical_path] = content_files
    return logical_path_map

