    logical_path_map = {}
    for item in inventory:
        logical_path = item.logical_path
        content_files = set([item.content_file])
        if logical_path in logical_path_map:
            logical_path_map[logical_path].update(content_files)
        else:
            logical_path_map[logical_path] = content_files
    return logical_path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for version_details in inventory:
        # Skip versions from before this one
        if version_details["version"] < version:
            continue
        # Iterate over the files in this version's inventory
        for content_file in version_details["files"]:
            # Skip files that are not in the current version's inventory
            if content_file["version"] != version:
                continue
            # Get the logical path for this file
            logical_path = content_file["logical_path"]
            # Add file to the set of files at this logical path
            if logical_path in logical_path_map:
                logical_path_map[logical_path].add(content_file)
            else:
                logical_path_map[logical_path] = set([content_file])
    return {logical_path: sorted(file_list) for logical_path, file_list in logical_path_map.items()}

