def validate_fixity(self, fixity, manifest_files):
    if not isinstance(fixity, dict):
        raise TypeError("Fixity must be a dictionary")

    if "format" not in fixity:
        raise ValueError("'format' field must be present in fixity dictionary")

    if fixity["format"] != "METS":
        raise ValueError("Invalid fixity format: {}".format(fixity["format"]))

    if "p4" not in fixity:
        raise ValueError("'p4' field must be present in fixity dictionary")

    if fixity["p4"] != "1.0":
        raise ValueError("Invalid fixity version: {}".format(fixity["p4"]))

    for df, fhash in fixity.items():
        if df not in manifest_files:
            raise ValueError("Reference to file not in manifest: {}".format(df))

        if not isinstance(fhash, str):
            raise TypeError("File hash must be a string")

        fext = os.path.splitext(df)[1]
        if fext == ".xml":
            continue

        try:
            extension_to_hashing_algorithm = {
                ".tif": hashlib.sha256,
                ".jp2": hashlib.sha256,
                ".png": hashlib.sha512,
            }
            alg = extension_to_hashing_algorithm[fext]
            alg.update(fhash.encode("utf-8"))
        except KeyError:
            raise ValueError("Invalid file extension: {}".format(fext))

def validate_fixity(self, fixity, manifest_files):
