    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Invalid fixity block type: {}".format(type(fixity)))

    expected_keys = {'algorithm', 'hash', 'source'}
    for key in fixity:
        if key not in expected_keys:
            raise ValueError("Unknown key in fixity block: {}".format(key))

    if set(fixity) != expected_keys:
        raise ValueError("Missing required keys in fixity block: {}".format(expected_keys - set(fixity)))

    if not isinstance(fixity['algorithm'], str):
        raise ValueError("Invalid algorithm type in fixity block: {}".format(type(fixity['algorithm'])))

    if not isinstance(fixity['hash'], str):
        raise ValueError("Invalid hash type in fixity block: {}".format(type(fixity['hash'])))

    if not isinstance(fixity['source'], str):
        raise ValueError("Invalid source type in fixity block: {}".format(type(fixity['source'])))

    for filename in fixity['source']:
        if filename not in manifest_files:
            raise ValueError("File {} in fixity block is not listed in manifest".format(filename))

    return fixity

