    if not fixity:
        raise ValueError("Fixity block is missing from inventory")

    if not isinstance(fixity, dict):
        raise ValueError("Fixity block is not a valid dictionary")

    fixity_files = [file for file in fixity.keys()]
    for file in fixity_files:
        if file not in manifest_files:
            raise ValueError("File %s is not listed in the manifest" % file)

