    :param file_path: str, the absolute file path of the asset
    """
    TIFF_EXTENSIONS = ["tiff", "tif"]
    JPEG_EXTENSIONS = ["jpg", "jpeg"]
    PNG_EXTENSIONS = ["png"]

    asset = self.get_asset_by_basename(basename)
    if asset is None:
        extension = file_path.split(".")[-1]
        if extension.lower() in TIFF_EXTENSIONS:
            mimetype = "image/tiff"
