    return str(self)

def absorb(self, args):
    def is_absorbed_and_or(exp1, exp2):
        if exp1 == exp2:
            return exp1
        elif exp1.op == '&':
            arg1 = exp1.args[0]
            arg2 = exp1.args[1]
            if arg1 == arg2 == exp2:
                return arg1
            elif arg1 == arg2:
                return exp1
        elif exp1.op == '|':
            arg1 = exp1.args[0]
            arg2 = exp1.args[1]
            if arg1 == arg2 == exp2:
                return exp1
            elif arg1 == arg2:
                return arg1
        return exp1 & exp2

    def is_absorbed_or_and(exp1, exp2):
        if exp1 == exp2:
            return exp1
        elif exp1.op == '&':
            arg1 = exp1.args[0]
            arg2 = exp1.args[1]
            if arg1 == arg2 == exp2:
                return arg2
            elif arg1 == arg2:
                return exp1
        elif exp1.op == '|':
            arg1 = exp1.args[0]
            arg2 = exp1.args[1]
            if arg1 == arg2 == exp2:
                return exp1
            elif arg1 == arg2:
                return arg1
        return exp1 | exp2

    def is_negative_absorbed_and_or(exp1, exp2):
        if exp1 == exp2:
            return exp1
        elif exp1.op == '&':
            arg1 = exp1.args[0]
            arg2 = exp1.args[1]
            if arg1 == exp2:
                return arg2
            elif arg2 == exp2:
                return arg1
        elif exp1.op == '|':
            arg1 = exp1.args[0]
            arg2 = exp1.args[1]
            if arg1 == arg2 == exp2:
                return exp1
            elif arg1 == arg2:
                return arg1
        return exp1 & exp2

    def is_negative_absorbed_or_and(exp1, exp2):
        if exp1 == exp2:
            return exp1
        elif exp1.op == '&':
            arg1 = exp1.args[0]
            arg2 = exp1.args[1]
            if arg1 == exp2:
                return arg2
            elif arg2 == exp2:
                return arg1
        elif exp1.op == '|':
            arg1 = exp1.args[0]
            arg2 = exp1.args[1]
            if arg1 == arg2 == exp2:
                return exp1
            elif arg1 == arg2:
                return arg1
        return exp1 | exp2

    result = []
    for arg in args:
        if arg.op == '&':
            arg1 = arg.args[0]
            arg2 = arg.args[1]
            if is_absorbed_and_or(arg1, arg2) or is_absorbed_or_and(arg1, arg2) or is_negative_absorbed_and_or(arg1, arg2) or is_negative_absorbed_or_and(arg1, arg2):
                result.append(is_absorbed_and_or(arg1, arg2))
            else:
                result.append(arg)
        else:
            result.append(arg)
    return result

def absorb(args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, (LogicalAND, LogicalOR)):
            if isinstance(arg.lhs, LogicalAND) and isinstance(arg.rhs, LogicalOR):
                new_args.append(arg.lhs.children[0])
            elif isinstance(arg.lhs, LogicalOR) and isinstance(arg.rhs, LogicalAND):
                new_args.append(arg.rhs.children[0])
        elif isinstance(arg, LogicalNOT) and isinstance(arg.child, LogicalAND):
            new_args.append(arg.child.children[0])
        else:
            new_args.append(arg)
    return new_args

def absorb(self, args):
    new_args = []
    for arg in args:
        new_args.append(self._absorb(arg))
    return new_args

