def _fromutc(self, dt):
    if not isinstance(dt, datetime):
        raise ValueError("dt must be a datetime object")
    if not dt.tzinfo:
        raise ValueError("dt must be timezone-aware")
    if self.tzinfo is None:
        raise ValueError("self.tzinfo must be specified")
    new_dt = dt.astimezone(self.tzinfo)
    if new_dt.tzinfo.utcoffset(new_dt) != self.tzinfo.utcoffset(dt):
        # DST change
        return [new_dt.replace(tzinfo=self.tzinfo), new_dt.replace(tzinfo=self.tzinfo + timedelta(hours=1))]
    return new_dt.replace(tzinfo=self.tzinfo)

def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """

    norm_obj = {}
    for key, val in self.items():
        if isinstance(val, int) or isinstance(val, float):
            # Normalize int or float values to int
            norm_obj[key] = int(val)
        elif isinstance(val, bool):
            # Normalize boolean values to 0 or 1
            norm_obj[key] = int(val)
        elif isinstance(val, str):
            # Normalize string values to lowercase
            norm_obj[key] = val.lower()
        else:
            # Unsupported value type
            raise TypeError(f"Unsupported value type for key {key}: {type(val).__name__}")

    return relativedelta(**norm_obj)

def normalized(self):
    total_days = self.days + self.months * relativedelta.MONTHS_PER_YEAR
    total_hours = (total_days * relativedelta.HOURS_PER_DAY) + self.hours
    total_minutes = (total_hours * relativedelta.MINUTES_PER_HOUR) + self.minutes
    total_seconds = (total_minutes * relativedelta.SECONDS_PER_MINUTE) + self.seconds
    return relativedelta(days=total_days, hours=total_hours, minutes=total_minutes, seconds=total_seconds)

