    default_version = {"module1": "0.1", "module2": "1.0"}

    # Initialize the extracted version information as a dictionary
    extracted_version = {}

    # Loop through the modules in the default version dictionary
    for module_name, default_version in default_version.items():
        try:
            # Try to import the module
            module = importlib.import_module(module_name)

            # Try to extract the version attribute from the module
            version = getattr(module, "version", default_version)

            # Add the module name and extracted version to the dictionary
            extracted_version[module_name] = str(version)

        except ModuleNotFoundError:
            # If the module cannot be found, use the default version
            extracted_version[module_name] = default_version

    return extracted_version

def get_versions():
    """Get version information or return default if unable to do so."""
