def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s).

    Args:
        commands: The command(s) to run as a list of strings.
        args: The arguments to the command(s) as a list of strings.
        cwd: The working directory to run the command from.
        verbose: Whether to print Standard Output and Error.
        hide_stderr: Whether to hide Standard Error.
        env: A dictionary of environment variables.

    """
    output = b""
    try:
        process = subprocess.Popen(commands, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        (stdout, stderr) = process.communicate(input=args)
        if hide_stderr:
            stderr = None
        if verbose:
            if stdout:
                print(stdout.decode("utf-8"))
            if stderr:
                print(stderr.decode("utf-8"))
        output = stdout or stderr
    except Exception as e:
        raise ProgramError("Error when running command: {}\n{}".format(commands, str(e)))
    finally:
        if process.returncode != 0:
            raise ProgramError("Command exited with non-zero return code: {}".format(process.returncode))
    return output.decode("utf-8")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    # Define the default arguments for the command
    if commands is None or not commands:
        raise ValueError("Invalid command specified. Commands cannot be None or empty")
    if args is None:
        args = []
    if cwd is None:
        cwd = os.getcwd()
    if env is None:
        env = os.environ
    if hide_stderr:
        stderr = subprocess.DEVNULL
    else:
        stderr = subprocess.STDOUT

    # Split the commands into a list of commands to run
    commands = commands.split()

    # Create a list of commands to run for each command provided
    commands_to_run = []
    for command in commands:
        cmd = [command] + args
        commands_to_run.append(cmd)

    # Run the commands
    outputs = []
    for cmd in commands_to_run:
        try:
            output = subprocess.check_output(cmd, cwd=cwd, env=env, stderr=stderr, shell=False, universal_newlines=True)
            outputs.append(output)
        except subprocess.CalledProcessError as e:
            err = "Error running command: '{}'".format(" ".join(cmd))
            raise ProgramError(err)

    # Return the output of the last command
    return outputs[-1] if len(outputs) > 0 else b''

