def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0
    visited_objects = set()
    for root_path in self.get_root_paths():
        for base_object_path in self.list_base_object_paths(root_path):
            num_objects += 1
            try:
                object_path = self.get_object_path(root_path, base_object_path)
            except ObjectNotFoundError:
                self.logger.warning(f"Object not found: {root_path}/{base_object_path}")
                continue
            if object_path in visited_objects:
                continue
            visited_objects.add(object_path)
            try:
                object_id = self.load_object_id(object_path)
            except LoadError:
                self.logger.warning(f"Object loading failed: {root_path}/{base_object_path}")
                continue
            if validate_objects and not self.validate_object(object_id):
                self.logger.warning(f"Object validation failed: {root_path}/{base_object_path}")
                continue
            good_objects += 1
            if check_digests:
                try:
                    self.check_digest(object_id)
                except DigestError:
                    self.logger.warning(f"Digest check failed: {root_path}/{base_object_path}")
                    continue
            if show_warnings and self.logger.warning_enabled:
                for warning in self.get_object_warnings(object_id):
                    self.logger.warning(f"Object warning: {root_path}/{base_object_path}:\n    {warning}")
    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if re.match(r'^0\d+$', version):
        return str(int(version) + 1)
    else:
        return f'{version}.1'

def next_version(version):
    """Next version identifier following existing pattern."""
    if version.startswith("v"):
        version = version[1:]
    parts = version.split(".")
    if len(parts) != 3:
        raise ValueError(f"Invalid version format: {version}")
    major, minor, patch = parts
    patch = str(int(patch) + 1)
    return f"{major}.{minor}.{patch}"

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.
    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.
    """
    root_inventory = {}
    for version_dir in version_dirs:
        inventory_file = os.path.join(version_dir, 'inventory.json')
        try:
            with open(inventory_file) as f:
                inventory = json.load(f)
        except FileNotFoundError:
            raise CommandError(f"Inventory file for version {version_dir} not found.")
        if 'contents' in inventory:
            for filename, content_digest in inventory['contents'].items():
                if filename not in root_inventory:
                    root_inventory[filename] = content_digest
                elif content_digest != root_inventory[filename]:
                    raise CommandError(f"Content digest for file {filename} does not match.")

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, 'inventory.json')
        if not os.path.exists(inventory_path):
            raise ValidationError(f'Missing inventory file in version directory {version_dir}')
        inventory_content = json.load(open(inventory_path, mode='rb'))
        for content_digest in inventory_content:
            if content_digest not in self.inventory:
                raise ValidationError(f'Content digest {content_digest} in inventory is not present in the root inventory')
        self.version_inventories.append(inventory_content)

def validate_version_inventories(self, version_dirs):
    """
    Validates that each version has an inventory up to that point and that any content digests
    are recorded in the root inventory.

    version_dirs is an array of version directory names and is assumed to be in version sequence (1, 2, 3...).
    """
    for version_dir in version_dirs:
        inventory_file = os.path.join(version_dir, "inventory.txt")
        if not os.path.isfile(inventory_file):
            raise OSError(f"Inventory file {inventory_file} not found")

        with open(inventory_file, "r") as f:
            inventory = f.readlines()

        if len(inventory) == 0:
            raise ValueError(f"Empty inventory file: {inventory_file}")

        root_inventory_file = os.path.join(self.root_dir, "inventory.txt")
        with open(root_inventory_file, "a") as f:
            for line in inventory:
                if line not in f.readlines():
                    f.write(line)

        # Hash the inventory file and compare it to the hash in the root inventory
        with open(inventory_file, "rb") as f:
            hash_ = hashlib.sha256(f.read()).hexdigest()

        root_inventory_hashes = {}
        with open(root_inventory_file, "r") as f:
            for line in f.readlines():
                key, value = line.split("  ")
                root_inventory_hashes[key] = value

        if hash_ not in root_inventory_hashes.values():
            raise ValueError(f"Hash of inventory file {inventory_file} not found in root inventory")

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """

    # Initialize return value to None
    result = None

    # Check if path is a directory
    if os.path.isdir(path):
        # Check if path contains "0=*"
        if re.search(r"0=\*", os.listdir(path)):
            # Check if path contains "_root_"
            if re.search(r"_root_", os.listdir(path)):
                result = "root"
            # Check if path contains "inventory"
            elif re.search(r"inventory", os.listdir(path)):
                result = "file"
            else:
                # Check if path contains "namaste"
                if re.search(r"namaste", os.listdir(path)):
                    result = "object"
                else:
                    raise Exception("Path is not a root, object, or file.")
        else:
            raise Exception("Path does not contain '0=*' Namaste file.")
    else:
        raise Exception("Path is not a directory.")

    return result

def find_path_type(path):
    if path.endswith(ocfl_inventory_extensions):
        return 'file'
    elif os.path.isdir(path):
        with open(path + '/0=ocfl_object_1.0', 'rb') as f:
            if pickle.dump(ocfl_object_1_0_fmt.decode('utf-8') in f.read():
                return 'object'
            elif pickle.dump(ocfl_root_1_0_fmt.decode('utf-8') in f.read():
                return 'root'
            else:
                raise Exception('Invalid Object')
    else:
        raise Exception('Not a directory')

