def deep_merge_nodes(nodes):
    result = []
    for key, value in nodes:
        if isinstance(value, Node) and not value.resolved:
            for existing_key, existing_value in result:
                if key.value == existing_key.value:
                    # Merge ValueNodes with the same key
                    if isinstance(value, ValueNode) and isinstance(existing_value, ValueNode):
                        result.remove((existing_key, existing_value))
                        result.append((key, ValueNode(value.value, value.style, update=True)))
                    # Merge MappingNodes by combining their key-value pairs
                    elif isinstance(value, MappingNode) and isinstance(existing_value, MappingNode):
                        result.remove((existing_key, existing_value))
                        result.append((key, MappingNode(value.value, value.styles).combine(existing_value)))
                    # Merge SequenceNodes by appending their values
                    elif isinstance(value, SequenceNode) and isinstance(existing_value, SequenceNode):
                        result.remove((existing_key, existing_value))
                        result.append((key, SequenceNode(value.value, value.style).combine(existing_value)))
            else:
                result.append((key, value))
        else:
            result.append((key, value))
    return result

def deep_merge_nodes(nodes):
    # Initialize an empty dictionary to hold the merged nodes
    merged_nodes = {}

    # Loop through each node in the list of nodes
    for node in nodes:
        # Check if the current node is a MappingNode or a SequenceNode
        if isinstance(node, (ruamel.yaml.nodes.MappingNode, ruamel.yaml.nodes.SequenceNode)):
            # If the node is a MappingNode, recursively call the deep_merge_nodes function on the node's value
            if isinstance(node, ruamel.yaml.nodes.MappingNode):
                node.value = deep_merge_nodes(node.value)
            # If the node is a SequenceNode, recursively call the deep_merge_nodes function on the node's value
            elif isinstance(node, ruamel.yaml.nodes.SequenceNode):
                node.value = deep_merge_nodes(node.value)
        # If the node is not a MappingNode or a SequenceNode, set the node as the value of the merged_nodes dictionary
        else:
            merged_nodes[node.value] = node

    # Return the merged nodes
    return ruamel.yaml.nodes.Node(merged_nodes)

