def parse_arguments(*unparsed_arguments):
    global_namespace = None
    namespaces = {}

    # Use a default subparser if there are no subparsers
    if not hasattr(self, "subparsers"):
        default_subparser = argparse.ArgumentParser(prog="default")
        subparsers = default_subparser.add_subparsers(dest="subparser")
        namespaces["default"] = default_subparser.parse_args(unparsed_arguments)

    # Parse each subparser
    for name, subparser in self.subparsers:
        # Add the subparser to the argument list with the required final arg
        pargs = unparsed_arguments + [subparser.get_default()]
        namespaces[name] = subparser.parse_args(pargs)

        # Remove the subparser from the args to prevent issues with argparse
        i = unparsed_arguments.index(subparser.get_default())
        del unparsed_arguments[i]

    # If global arguments were provided, parse them now
    if unparsed_arguments:
        if global_namespace:
            del unparsed_arguments[0]
        global_namespace = self._subparsers_action.parse_args(unparsed_arguments)

    return {"subparser": namespaces, "global": global_namespace}

