def size_to_bytes(size):
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    try:
        num, unit = size.split()
        if unit.lower() in ["b", "byte", "bytes"]:
            return int(num)
        elif unit.lower() in ["k", "kb", "kilobyte", "kilobytes"]:
            return int(num) * 1000
        elif unit.lower() in ["m", "mb", "megabyte", "megabytes"]:
            return int(num) * 1000000
        elif unit.lower() in ["g", "gb", "gigabyte", "gigabytes"]:
            return int(num) * 1000000000
        elif unit.lower() in ["t", "tb", "terabyte", "terabytes"]:
            return int(num) * 1000000000000
        elif unit.lower() in ["p", "pb", "petabyte", "petabytes"]:
            return int(num) * 1000000000000000
        elif unit.lower() in ["e", "eb", "exabyte", "exabytes"]:
            return int(num) * 1000000000000000000
        else:
            raise ValueError("Invalid unit provided")
    except:
        raise ValueError("Invalid input format")

