def split(s, platform='this'):
    "Platform-aware splitting for command-line arguments"
    if platform == 'this':
        parts = _split(s)
    elif platform in {"1", "posix", "unix"}:
        parts = ["".join(s)]
    elif platform in {"0", "windows"}:
        parts = cmd.exe(s)
    else:
        raise ValueError("Unsupported platform: {}".format(platform))
    return parts

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = (sys.platform == 'win32')
    elif platform == 0:
        platform = True
    else:
        platform = False

    if platform:
        return shlex.split(s, posix=True)
    else:
        return shlex.split(s, posix=False)

def prepare_repository_from_archive(archive_path, filename=None, tmp_path='/tmp'):
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.
    """
    archiver = archiver_for_path(archive_path)
    if filename is None:
        filename = os.path.basename(archive_path)
    if not os.path.exists(os.path.join(tmp_path, filename)):
        if HAVE_P7ZIP and archiver is TK:
            subprocess.call([
                '7z', 'x',
                '-o{}'.format(tmp_path),
                '-y',
                archive_path
            ])
        elif HAVE_BZIP and archiver is TBZ2:
            subprocess.call([
                'bzip2', '-d',
                '-k',
                archive_path
            ])
    return os.path.join(tmp_path, filename)

def prepare_repository_from_archive(archive_path, filename=None, tmp_path="/tmp"):
    if not os.path.isfile(archive_path):
        raise ValueError(f"Invalid archive_path: {archive_path}")
    tmp_dir = os.path.join(tmp_path, secrets.token_hex(8))
    if not os.path.isdir(tmp_dir):
        os.makedirs(tmp_dir)
    subprocess.run(["tar", "xf", archive_path, "-C", tmp_dir])
    repo_path = os.path.join(tmp_dir, filename) if filename is not None else tmp_dir
    return repo_path

