def parse_frequency(frequency):
    if not frequency:
        return None
    if frequency.lower() == 'always':
        return None
    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError('Frequency should have two parts')
    amount = parts[0]
    unit = parts[1].lower()

    if unit == 'weeks':
        return datetime.timedelta(weeks=int(amount))
    elif unit == 'days':
        return datetime.timedelta(days=int(amount))
    elif unit == 'hours':
        return datetime.timedelta(hours=int(amount))
    elif unit == 'minutes':
        return datetime.timedelta(minutes=int(amount))
    elif unit == 'seconds':
        return datetime.timedelta(seconds=int(amount))
    else:
        raise ValueError('Invalid frequency unit')

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    match = re.match(r"^(?P<count>\d+) (?P<unit>week|weeks|day|days)$", frequency)
    if not match:
        raise ValueError(f"Invalid frequency format: {frequency}")
    unit_and_count = match.groupdict()
    unit_and_count["unit"] = unit_and_count["unit"].lower()
    if unit_and_count["unit"] not in ["week", "day"]:
        raise ValueError(f"Unsupported frequency unit: {unit_and_count['unit']}")
    return datetime.timedelta(**{unit_and_count["unit"]: int(unit_and_count["count"])})

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError("Invalid frequency string: " + frequency)
    amount = int(parts[0])
    unit = parts[1][:-1].lower()
    if unit == "sec":
        return datetime.timedelta(seconds=amount)
    elif unit == "min":
        return datetime.timedelta(minutes=amount)
    elif unit == "hour":
        return datetime.timedelta(hours=amount)
    elif unit == "day":
        return datetime.timedelta(days=amount)
    elif unit == "week":
        return datetime.timedelta(weeks=amount)
    elif unit == "month":
        return datetime.timedelta(weeks=amount)
    elif unit == "year":
        return datetime.timedelta(days=amount*365)
    else:
        raise ValueError("Unknown frequency unit: " + unit)

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == 'always':
        return None
    match = re.match(r'^(\d+) (\w+)', frequency.strip())
    if not match:
        raise ValueError("Invalid frequency string: {}".format(frequency))
    num, unit = match.groups()
    if unit.endswith('s'):
        unit = unit[:-1]
    return getattr(datetime, 'timedelta_{}'.format(unit))(*[int(v) for v in (num,)])

