def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        addresses = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False

    for address in addresses:
        if address.family == socket.AF_INET and address.sockaddr[0] == '127.0.0.1':
            return True
        elif address.family == socket.AF_INET6 and address.sockaddr[0] == '::1':
            return True

    return False

