def subprocess_run_helper(func, *args, timeout, extra_env=None):
    if not callable(func):
        raise TypeError("func must be a callable function")
    if timeout <= 0:
        raise ValueError("timeout must be a positive integer")

    cmd = [sys.executable, "-c", func.__module__ + "." + func.__qualname__] + list(args)
    env = os.environ.copy()
    if extra_env:
        env.update(extra_env)
    try:
        return subprocess.run(cmd, timeout=timeout, check=True, capture_output=True, env=env).stdout.decode("utf-8")
    except CalledProcessError as exc:
        raise RuntimeError("failed to execute subprocess") from exc
    except TimeoutExpired as exc:
        raise RuntimeError("subprocess timed out") from exc

def subprocess_run_helper(func, *args, timeout, extra_env=None):
    """
    Run a function in a sub-process.

    Parameters
    ----------
    func : function
        The function to be run.  It must be in a module that is importable.
    *args : str
        Any additional command line arguments to be passed in
        the first argument to ``subprocess.run``.
    extra_env : dict[str, str]
        Any additional environment variables to be set for the subprocess.
    """
    if not callable(func):
        raise TypeError(f"func must be a callable, not {type(func).__name__}")
    if not timeout or timeout <= 0:
        raise ValueError("Timeout must be a positive integer")
    if isinstance(extra_env, dict):
        env = os.environ.copy()
        if extra_env:
            env.update(extra_env)
    else:
        env = extra_env
    cmd = [sys.executable, "-c", "import " + func.__module__ + "; func()" + str(args)]
    try:
        result = subprocess.run(cmd, timeout=timeout, env=env)
        if result.returncode != 0:
            raise subprocess.CalledProcessError(result.returncode, cmd)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Function returned non-zero exit status: {e}")
    except subprocess.TimeoutExpired as e:
        raise RuntimeError(f"Function timed out after {timeout} seconds.")

def _resolve_string(matcher):
    import os
    name, default = matcher.groups()
    if name not in os.environ:
        if default is not None:
            return default
        raise EnvironmentError(f"environment variable {name} not found")
    return os.environ[name]

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    name = matcher.groupdict.get('name')
    default = matcher.groupdict.get('default')
    if name not in os.environ and default is None:
        raise ValueError(f'{name} is not defined in environment, and no default value is provided')
    return os.environ.get(name, default)

