def run_command(command, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    # Check if the command is a list
    if not isinstance(command, list):
        raise TypeError("Expected command to be a list")

    # Check if the args is a dict
    if not isinstance(args, dict):
        raise TypeError("Expected args to be a dict")

    # Check if cwd is a string or None
    if not (cwd is None or isinstance(cwd, str)):
        raise TypeError("Expected cwd to be a string or None")

    # Check if verbose is a bool
    if not isinstance(verbose, bool):
        raise TypeError("Expected verbose to be a bool")

    # Check if hide_stderr is a bool
    if not isinstance(hide_stderr, bool):
        raise TypeError("Expected hide_stderr to be a bool")

    # Check if env is a dict or None
    if not (env is None or isinstance(env, dict)):
        raise TypeError("Expected env to be a dict or None")

    # Create a list of args
    command_args = []
    for arg, value in args.items():
        command_args.append(f"--{arg}={value}")

    # Join the command and args
    command_string = " ".join(command + command_args)

    # Create a subprocess
    process = subprocess.Popen(command_string, cwd=cwd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)

    # Read the output and error messages
    messages = {"success": None, "error": None}
    while process.poll() is None:
        output = process.stdout.readline()
        if output:
            messages["success"] = output.decode("utf-8").strip()
        error = process.stderr.readline()
        if error:
            messages["error"] = error.decode("utf-8").strip()

    # Wait for the process to finish
    process.wait()

    # Return the success and error messages
    if messages["success"] or messages["error"]:
        return {"success": messages["success"], "error": messages["error"]}
    else:
        return messages

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    command = [str(x) for x in commands] + [str(x) for x in args]
    try:
        output = subprocess.check_output(command, cwd=cwd, stderr=subprocess.PIPE if hide_stderr else subprocess.STDOUT, env=env).decode()
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Command failed with exit code {e.returncode}: {e.output.decode()}")
    if verbose:
        print(output)

