def find_roots(graph: rdflib.graph, prop: rdflib.term.URIRef, roots: Optional[Set[rdflib.term.Node]] = None) -> Set[rdflib.term.Node]:
    if not roots:
        roots = set()
    for s, p, o in graph:
        if p == prop:
            if o not in roots:
                roots.add(o)
                find_roots(graph, o, roots)
    return roots

def find_roots(graph, prop, roots=None):
    if roots is None:
        roots = set()
    todo = set(graph.nodes())
    while todo:
        node = todo.pop()
        if not graph.succ[node]:
            roots.add(node)
        else:
            for p in graph.succ[node]:
                if p is prop and p not in roots:
                    roots.add(p)
                else:
                    todo.add(p)
    return roots

def find_roots(graph, prop):
    todo = set()
    done = set()
    for node in graph.get_nodes():
        if node not in done:
            todo.add(node)
        while todo:
            node = todo.pop()
            parents = graph.get_parents(node, prop) - {node}
            not_done = parents - done
            if not_done:
                for p in not_done:
                    todo.add(p)
            else:
                done.add(node)
    return done

def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()

    todo = Queue()
    done = set()

    for node in graph.nodes:
        if len(graph.get_parents(node, prop)) == 0:
            roots.add(node)
        else:
            todo.push(node)

    while todo:
        node = todo.pop()
        children = graph.get_children(node, prop)
        for child in children:
            if len(graph.get_parents(child, prop)) == 0:
                roots.add(child)
            else:
                todo.push(child)

    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """

    if roots is None:
        roots = set()

    for node in graph.nodes:
        if not graph.successors(node, prop):
            roots.add(node)
        else:
            roots -= graph.successors(node, prop)

    return roots

