def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if dumper is None:
        dumper = yaml.Dumper
    if isinstance(obj, text_type):
        return obj
    elif isinstance(obj, str):
        return dumper.represent_scalar("tag:yaml.org,2002:str", obj, style='"')
    elif isinstance(obj, Sequence):
        return dumper.represent_sequence("tag:yaml.org,2002:seq", obj, flow_style="Flow")
    elif isinstance(obj, Mapping):
        return dumper.represent_mapping("tag:yaml.org,2002:map", obj, flow_style="None")
    return obj

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    precondition.AssertType(obj, yaml.SafeRepresenter)

    if compatibility.PY2:
        output = yaml.dump(obj.data, dumper=dumper, LineBreak=compatibility.UNICODE_BREAK)
    else:
        output = yaml.dump(obj.data, dumper=dumper, LineBreak=compatibility.STRING_BREAK)

    return output.rstrip()

def build_app_logger(name='app', logfile='app.log', debug=True):
    """
    General purpose application logger. Useful mainly for debugging
    """
    level_map = {
        True: logging.DEBUG,
        False: logging.INFO
    }
    level = level_map[debug]

    if not os.path.isfile(logfile):
        with open(logfile, 'w'):
            logging.getLogger(name).addHandler(logging.FileHandler(logfile))

    logging.getLogger(name).setLevel(level)

    return logging.getLogger(name)

def build_app_logger(name='app', logfile='app.log', debug=True):
    log_format = '%(asctime)s    %(levelname)s:%(message)s'
    if debug:
        lvl = logging.DEBUG
    else:
        lvl = logging.INFO
    formatter = logging.StreamHandler(os.path.join(logfile))
    formatter.setLevel(lvl)
    formatter.setFormatter(log_format)
    return logging.getLogger(name)

