        raise LenaValueError("Histograms with scale equal to zero can't be rescaled.")
    else:
        self._scale /= other
        self.histogram /= other
        self._sum = self.histogram * self.bin_width
        self._products = self._sum * self.bin_width
        return self._scale

def scale(self, other=None):
    if other is None:
        return self._scale
    elif isinstance(other, (int, float)):
        if self._scale == 0:
            raise LenaValueError("Cannot rescale graph with zero scale")
        self._scale = other
        for coordinate in self.coordinates:
            coordinate.values = coordinate.values * self._scale
        for error in self.errors:
            error.values = error.values * self._scale
    else:
        raise TypeError(f"unsupported type {type(other)} for scale")

