def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    if explicit_mc:
        return explicit_mc

    bases = [base for base in bases if isinstance(base, type)]

    if not bases:
        raise TypeError("No bases given")

    bases = tuple(bases)

    if len(bases) == 1:
        return bases[0].__class__

    metaclasses = {base.__class__ for base in bases}

    metaclass = None

    for meta in reversed(metaclasses):
        if issubclass(meta, type):
            metaclass = meta
            break

    if not metaclass:
        raise TypeError("No metaclass found")

    return metaclass

def determine_metaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit `__metaclass__`"""
    # Check if an explicit metaclass is defined
    if explicit_mc:
        # If so, use it
        return explicit_mc

    # Otherwise, try to find a `__metaclass__` attribute in the bases
    for base in bases:
        try:
            return base.__metaclass__
        except AttributeError:
            pass

    # If no `__metaclass__` attribute could be found, use the default metaclass
    return type

