    # Check if there is an explicit __metaclass__ class attribute
    if explicit_mc:
        return explicit_mc

    # Check if there are no explicit bases, but there is a global __metaclass__ variable
    global_mc = get_attribute("__metaclass__", None)
    if global_mc:
        return global_mc

    # Check if any of the bases have an explicit __metaclass__ class attribute
    for base in bases:
        if get_attribute("__metaclass__", base):
            return base

    # If all else fails, use the default metaclass
    return default_metaclass()

