def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        if request.get("id_token", None) != None and str(request.get("id_token", None)).startswith("m."):
            return True
        elif request.get("user_id", None) != None and str(request.get("user_id", None)).startswith("@"):
            return True
    except Exception as e:
        return False
    return False

def identify_request(request):
