        return request.META['Content-Type'].startswith('application/matrix')
    except KeyError:
        return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    if not request or not hasattr(request, "headers"):
        return False

    if request.headers.get("Content-type", "") == "application/x-www-form-urlencoded":
        return True

    if request.headers.get("Accept", "") == "application/json":
        return True

    return False

def identify_request(request: RequestType) -> bool:
    # Check if the request has a valid method
    if request.method != "GET" and request.method != "POST":
        return False

    # Check if the request has a valid content-type header
    if not request.headers.get("content-type"):
        return False

    # Check if the request has a valid body
    if not request.body:
        return False

    # Check if the request has a valid header
    if not request.headers.get("X-Launchpad-Request"):
        return False

    # The request appears to be a valid Matrix request
    return True

