def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    splits = text.split('\n')
    for index, split in enumerate(splits):
        if split.startswith('{}('):
            _extract_tags = ''
            for char in split:
                if char == ')':
                    break
                _extract_tags += char
            _extract_tags = _extract_tags[len('{}('):]
            tags.update(_extract_tags.rstrip(', ).').split(','))

    if replacer is not None:
        for i, tag in enumerate(tags):
            tags.add(replacer(tag))
            tags.remove(tag)

    return tags, text

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    lines = text.splitlines()
    for line in lines:
        if line.startswith('```'):
            continue
        for word in line.split():
            if word.startswith('%'):
                tag = word[1:]
                tags.add(tag)
                if replacer is not None:
                    word = replacer(tag)
                line = line.replace(word, word)
    if replacer is not None:
        text = '\n'.join(lines)
    return (tags, text)

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    new_text = []
    snippet = None

    for line in text.splitlines():
        if '<' in line and '>' in line:
            # Inside a block: accumulate lines and ignore tag finding
            if snippet is None:
                snippet = []
            snippet.append(line)
            continue
        elif snippet is not None:
            # We just left a block, handle the accumulated lines
            new_text.append(snippet.pop(0))
            if not snippet:
                snippet = None

        tag = re.search(r'\<([^\>]+)\>', line)
        if tag:
            tags.add(tag.group(1))
            if replacer:
                line = re.sub(r'\<([^\>]+)\>', replacer, line)
        new_text.append(line)

    return tags, ''.join(new_text).strip()

def process_text_links(text):
    def linkify(m):
        html = '<a href="{}">{}</a>'.format(m.group(0), m.group(1))
        return html

    def add_attributes(url, text):
        link = '<a href="{}" {}>{}</a>'.format(url, 'target="_blank"', text)
        return link

    def default_links_factory_with_additional(additional_links):
        def factory(pid, **kwargs):
            links = default_links_factory(pid)
            for link in additional_links:
                links[link] = additional_links[link].format(pid=pid, scheme=request.scheme, host=request.host)
            return links

        return factory

    def link_attrs(self, func):
        @libmarkdown.e_flags_callback
        def _link_attrs_func(string, size, context):
            ret = func(string[:size])
            if ret is not None:
                buf = ctypes.create_string_buffer(ret)
                self._alloc.append(buf)
                return ctypes.addressof(buf)

        self._link_attrs_func = _link_attrs_func
        return func

    _PATH_RE = re.compile(r"\s*[\"'](.*?)[\"']")
    _URL_RE = re.compile(r"\s*http(s)?://")
    memoized_urls = {}

    text = default_links_factory_with_additional({})(text, memoized_urls)
    text = linkify(text)
    text = add_attributes(text)
    text = link_attrs(text)

    return text

public static string ProcessTextLinks(string text)
{
    // Normalize newlines and whitespace
    text = text.Replace("\n", " ").Trim();
    // Match links and add href link to each match
    MatchCollection matches = Regex.Matches(text, @"\bhttps?://([\w-]+\.)+[\w-]+(/[\w ./?%&=]*)?");
    foreach (Match match in matches)
    {
        string replacement = string.Format("<a target=\"_blank\" href=\"{0}\">link</a>", match.Value);
        text = text.Replace(match.Value, replacement);
    }
    // Match text-based links and linkify
    matches = Regex.Matches(text, @"([\w-]+\.)+[\w-]+\.\w+");
    foreach (Match match in matches)
    {
        string replacement = string.Format("<a target=\"_blank\" href=\"{0}\">{1}</a>", match.Value, match.Value);
        text = text.Replace(match.Value, replacement);
    }
    return text;
}

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re

    def memoized_to_url(m):
        # to_url uses None to signal not to replace the text,
        # so we use a different sentinel value.
        value = memoized_urls.get(m.group(0), _NO_URL)
        if value is _NO_URL:
            value = to_url(m)
            memoized_urls[m.group(0)] = value
        return value

    def to_url(m):
        if m.group(1):
            return m.group(0)  # It's an http(s) url.
        path = m.group(0)

        if path.startswith('/'):
            path = os.path.relpath(path, buildroot)
        elif path.startswith('..'):
            # The path is not located inside the buildroot, so it's definitely not a BUILD file.
            return None
        else:
            # The path is located in the buildroot: see if it's a reference to a target in a BUILD file.
            parts = path.split(':')
            if len(parts) == 2:
                putative_dir = parts[0]
            else:
                putative_dir = path
            if os.path.isdir(os.path.join(buildroot, putative_dir)):
                build_files = list(BuildFile.get_build_files_family(
                    FileSystemProjectTree(buildroot),
                    putative_dir))
                if build_files:
                    path = build_files[0].relpath
                else:
                    return None

        if os.path.exists(os.path.join(buildroot, path)):
            # The reporting server serves file content at /browse/<path_from_buildroot>.
            return '/browse/{}'.format(path)
        else:
            return None

    def maybe_add_link(url, text):
        return '<a target="_blank" href="{}">{}</a>'.format(url, text) if url else text

    memoized_urls = {}
    return _PATH_RE.sub(lambda m: maybe_add_link(memoized_to_url(m), m.group(0)), text)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    def link_attrs(url):
        return "<a href=\"{}\" target=\"_blank\" class=\"my-link\">".format(url)

    def linkify(match):
        url = match.group(1)
        return link_attrs(url) if url else match.group(2)

    return re.sub(r"<a href=\"(\w+)\">(.+)</a>", linkify, text)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    matches = re.finditer(r'href="{0}"'.format(link), text)
    for match in matches:
        link = match.group(0)
        if "http" in link:
            link = '<a href="{0}" target="_blank" rel="noopener noreferrer">{1}</a>'.format(
                link,
                link.replace("http://", "").replace("https://", "").replace("www.", "").split("/")[0].split(".")[0]
            )
        else:
            link = '<a href="{0}.html" target="_blank" rel="noopener noreferrer">{1}</a>'.format(
                link.replace("/", ""),
                link
            )
        text = text.replace(match.group(0), link)
    return text

def fetch_content_type(url: str) -> Optional[str]:
    if not scheme in ('http', 'https', 'ftp', 'ftps'):
        return None
    req = Urllib2HeadRequest(url, headers={'Host': netloc})
    resp = urlopen(req)
    try:
        if hasattr(resp, 'code') and resp.code != 200 and scheme not in ('ftp', 'ftps'):
            return None
        return resp.info().get('content-type', '')
    finally:
        resp.close()

