def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if len(tag) < 1:
        return False
    elif len(tag) > 64:
        return False
    elif not re.match("^[a-zA-Z0-9\\-_]+$", tag):
        return False
    else:
        return True

