def test_tag(tag: str) -> bool:
    """
    Test a word whether it could be accepted as a tag.

    Args:
        tag (str): The word to test

    Returns:
        (bool): True if the tag is valid, False otherwise
    """
    if len(tag) < 1:
        return False
    if tag.isdigit():
        return False
    for c in tag:
        if not (c.isalnum() or c == '_'):
            return False
    return True

