def xml_children_as_dict(node):
    "Turn the children of node <xml> into a dict, keyed by tag name. This is only a shallow conversation - child nodes are not recursively processed."
    children = {}
    for child in node:
        if child.tag not in children:
            children[child.tag] = [child]
        else:
            children[child.tag].append(child)
    return children

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    children = {}
    for child in node.getchildren():
        tag = child.tag
        if tag in children:
            if not isinstance(children[tag], list):
                children[tag] = [children[tag]]
            children[tag].append(child)
        else:
            children[tag] = child
    return children

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    return {child.tag: child for child in node}

def xml_children_as_dict(node):
