    """
    children = node.getchildren()
    return {child.tag: child for child in children}

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not document_path:
        document_path = "/.well-known/nodeinfo"

    document, code, exception = fetch_document(
        host=urlparse(url).netloc, path=document_path
    )
    if exception:
        raise Exception("Error retrieving NodeInfo document: %s" % exception)
    if code != 200:
        raise Exception("Error retrieving NodeInfo document: HTTP error %d" % code)

    return parse_nodeinfo(document)

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    try:
        server_url = url.split("://")[1]
    except AttributeError:
        raise ValueError("Invalid URL format")

    if document_path:
        if not document_path.startswith("/"):
            document_path = "/" + document_path
    else:
        document_path = "/.well-known/nodeinfo"

    document, response_code, response_exception = fetch_document(
        server_url, document_path
    )

    if response_code != 200:
        raise ConnectionError(
            f"Error retrieving NodeInfo document from {url}: {response_code}"
        )

    return parse_diaspora_webfinger(document)

def get_nodeinfo_well_known_document(url, document_path=None):
    if document_path:
        path = join(document_path, ".well-known")
    else:
        path = join(url, ".well-known")
    document, code, exception = fetch_document(path)
    if exception:
        return None
    return document

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    if not public_key or not doc or not signature:
        raise ValueError("public_key, doc and signature are required")

    try:
        doc = etree.fromstring(doc)
    except etree.ParseError:
        raise ValueError("doc must be a valid XML string")

    sig = doc.find(".//")
    if sig is None:
        raise ValueError("doc must contain a signature element")

    try:
        nodes = []
        for node in doc.iter():
            if node.tag == sig.tag:
                nodes.append(node)
        nodes.remove(sig)
        signature = signature.strip()
        for node in nodes:
            if node.tag == sig.tag:
                if node.text.strip() != signature:
                    raise ValueError("signature mismatch")
    except ValueError:
        raise ValueError("signature mismatch")

    try:
        cert_file = _get_certificate(public_key)
    except FileNotFoundError:
        raise ValueError("certificate file not found")

    try:
        pub_key = RSA.importKey(cert_file.text)
    except RSAError:
        raise ValueError("certificate is not a valid RSA key")

    message = "".join([etree.tostring(node) for node in nodes])
    try:
        verifier = PKCS1_v1_5.new(pub_key)
        digest = SHA.new(message)
        verifier.verify(digest, signature)
    except TypeError:
        raise ValueError("signature is not valid")

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    data = json.loads(document)
    if "id" not in data:
        raise ValueError("'id' field missing from webfinger document")
    elif "application/json" not in data["id"]:
        raise ValueError("'id' field must be in 'application/json' format")
    if "links" not in data:
        raise ValueError("'links' field missing from webfinger document")
    elif not isinstance(data["links"], list):
        raise ValueError("'links' field must be a list")
    for link in data["links"]:
        if not isinstance(link, str):
            raise ValueError("Links fields must be in string format")
        elif not link.startswith("\""):
            raise ValueError("Link must start with \"")
        if not link.endswith("\""):
            raise ValueError("Link must end with \"")
    return data

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if document.startswith("<"):
        # XRD format
        return parse_diaspora_webfinger_xrd(document)
    else:
        # JSON format
        return parse_diaspora_webfinger_json(document)

def parse_diaspora_webfinger(document):
    webfinger = {}
    try:
        webfinger = json.loads(document)
        return webfinger
    except JSONDecodeError:
        logger.warning("parse_diaspora_webfinger: invalid JSON document given: %s", document)
        return None

def parse_diaspora_webfinger(document: str) -> Dict:
    webfinger = {}
    try:
        j = json.loads(document)
        if "subject" in j:
            webfinger["subject"] = j["subject"]
        if "aliases" in j:
            webfinger["aliases"] = j["aliases"]
        if "properties" in j:
            webfinger["properties"] = j["properties"]
        if "links" in j:
            webfinger["links"] = j["links"]
        if "contacts" in j:
            webfinger["contacts"] = j["contacts"]
        if "public_key" in j:
            webfinger["public_key"] = j["public_key"]
        if "addresses" in j:
            webfinger["addresses"] = j["addresses"]
    except json.JSONDecodeError:
        logger.warning("Failed to parse Diaspora webfinger JSON.")
    return webfinger

def parse_diaspora_webfinger(document: str) -> Dict:
    try:
        result = diaspora.webfinger.parse(document)
    except ValueError as e:
        raise ParseError(f"Failed to parse Diaspora webfinger: {e}")
    return result

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    host = handle.split("@")[1]
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if exception:
        logger.warning("Try Failed. URL: %s, Error: %s", host, exception)
        return None
    return parse_webfinger(document)

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    host = handle.split("@")[1]
    document, code, exception = fetch_document(
        host=host,
        path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document is None:
        return None
    return parse_diaspora_webfinger(document)

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if not document:
        hostmeta = retrieve_diaspora_host_meta(host)
        if not hostmeta:
            return None
        url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
        document, code, exception = fetch_document(url)
        if exception:
