def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type

    :param settings_dirs: list of dir to look for ini type files
    :param spec_option: option to specify the output type (either 'json' or 'yaml')
    :return: list of fully qualified file names of the ini type files
    """
    try:
        ini_files = []
        for dir in settings_dirs:
            ini_files.extend(list_of_fully_qualified_file_names(dir, '.ini'))
        if spec_option == 'yaml':
            return [convert_ini_to_yaml(file) for file in ini_files]
        elif spec_option == 'json':
            return [convert_ini_to_json(file) for file in ini_files]
        else:
            raise ValueError("Invalid spec option: {}".format(spec_option))
    except OSError as e:
        return []

def list_of_file_names(settings_dirs: List[str], spec_option: bool):
    """ Create a new IniType complex type

    Args:
        settings_dirs (List[str]): list of directories to list
        spec_option (bool): whether to include special types

    Returns:
        list: list of fully qualified python filenames in the given directories

    """
    try:
        files = []
        for dir in settings_dirs:
            files += [os.path.join(dir, fname) for fname in os.listdir(dir) if spec_option or fname not in _SPECIAL_TYPES]
        return sorted(files)
    except OSError:
        return []

def list_of_file_names(settings_dirs, spec_option):
