    :param settings_dirs: List of directories.
    :param spec_option: Option for specifications.
    :return: list of full filenames in specified directory.
    """
    try:
        return sorted([
            os.path.join(directory, fname)
            for directory in settings_dirs
            for fname in os.listdir(directory)
            if spec_option.match(fname)
        ])
    except OSError:
        return []

