def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    try:
        spec_data = yaml.load(spec_content, Loader=Loader)
    except yaml.YAMLError as err:
        raise IRValidatorException(f"Error loading spec file: {err}")

    try:
        data = json.loads(spec_content)
    except json.JSONDecodeError as err:
        raise IRValidatorException(f"Error loading spec file: {err}")

    for key, value in data.items():
        if key in cls.mandatory_fields:
            if value is None or value == "":
                raise IRValidatorException(f"Mandatory field {key} is missing")

    return spec_data

def validate_from_content(spec_content):
    """Validates that spec (YAML) content has all required fields.

    :param spec_content: Content of spec file.
    :return: Dictionary with data loaded from a spec (YAML) file.
    """
    # Load the spec content as a dictionary
    spec = yaml.load(spec_content, Loader=yaml.FullLoader)

    # Check if the 'name' field is present in the spec
    if 'name' not in spec:
        raise IRValidatorException("The 'name' field is missing in the spec file.")

    # Check if the 'dir' field is present in the spec
    if 'dir' not in spec:
        raise IRValidatorException("The 'dir' field is missing in the spec file.")

    # Check if the 'modules' field is present in the spec
    if 'modules' not in spec:
        raise IRValidatorException("The 'modules' field is missing in the spec file.")

    # Check if the 'input' field is present in each module
    for module in spec['modules']:
        if 'input' not in module:
            raise IRValidatorException(f"The 'input' field is missing in the module '{module['name']}'.")

    # Check if the 'output' field is present in each module
    for module in spec['modules']:
        if 'output' not in module:
            raise IRValidatorException(f"The 'output' field is missing in the module '{module['name']}'.")

    # Return the loaded spec
    return spec

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    if yaml_file is None:
        raise ValueError("yaml_file parameter must be specified")

    default_schema = json.load(open(cls.default_schema_file, 'r'))

    try:
        data = yaml.load(open(yaml_file, 'r'), Loader=Loader)
    except Exception as e:
        raise IRValidatorException(
            "There was a problem loading the YAML file: " + e.__str__()
        )

    try:
        jsonschema.validate(data, default_schema)
    except ValidationError as ve:
        raise IRValidatorException(
            "The YAML file did not pass the schema validation: " + ve.__str__()
        )

    return data

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    try:
        with open(yaml_file, "r") as f:
            data = yaml.load(f)

        if not data:
            raise IRValidatorException("No data in YAML file.")

        mandatory_fields = ["filename", "extension", "file_type"]
        if not all(field in data for field in mandatory_fields):
            raise IRValidatorException(f"Mandatory fields missing: {', '.join(mandatory_fields)}")

        return data

    except FileNotFoundError:
        raise IRValidatorException(f"File not found: '{yaml_file}'.")

    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML file: {yaml_file}.")

using System.IO;
using YamlDotNet.RepresentationModel;

public static class YamlValidator
{
    public static Dictionary<string, string> ValidateFromFile(string yamlFile)
    {
        var yaml = new YamlStream();
        using (var reader = new StreamReader(yamlFile))
        {
            yaml.Load(reader);
        }

        var mandatoryKeys = new List<string>() { "name", "version" };
        var missingKeys = new List<string>();
        foreach (var key in mandatoryKeys)
        {
            if (!yaml.ContainsKey(key))
            {
                missingKeys.Add(key);
            }
        }

        if (missingKeys.Count > 0)
        {
            throw new IRValidatorException($"Mandatory data missing: {string.Join(", ", missingKeys)}");
        }

        return yaml.ToDictionary(y => (string)y.Key, y => (string)y.Value);
    }
}

def validate_from_file(yaml_file):
    """
    Validates that a YAML file has all required fields

    :param yaml_file: path to YAML file
    :return dict: Dictionary with data loaded from the YAML file
    """
    if not yaml_file:
        raise LookupError("YAML file argument must be supplied")
    try:
        data = yaml.load(open(yaml_file, "r"))
    except YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML file: {yaml_file}\n{e}")
    required_fields = data.pop("required_fields", [])
    missing_fields = []
    for req_field in required_fields:
        if req_field not in data:
            missing_fields.append(req_field)
    if missing_fields:
        raise IRValidatorException(f"The following required fields are missing from the YAML file: {', '.join(missing_fields)}")
    return data

def include_groups(parser_dict):
    """
    Resolves the include dict directive in the spec files.
    """
    include_dict = parser_dict['include']
    included_groups = {}
    for group, group_dict in include_dict.items():
        included_groups.update(self._include_groups(group_dict))
    parser_dict.update(included_groups)
    return parser_dict

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """
        if not self._config.include_groups:
            return parser_dict
        parser_dict = {k: v for k, v in parser_dict.items() if k in self._config.include_groups}
        return parser_dict

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """

        import utool as ut

        included_groups = set()
        for key, value in parser_dict.items():
            if isinstance(value, dict) and 'include' in value:
                include_specifiers = ut.to_list(value['include'])
                for include_specifier in include_specifiers:
                    include_key = include_specifier[0]
                    include_group = include_specifier[1]
                    if include_key not in included_groups:
                        included_groups.add(include_key)
                        included_group = self.spec[include_key]['group'][include_group]
                        for command in included_group:
                            parser_dict[command] = included_group[command]

        return parser_dict

def _include_groups(parser_dict):
    resulted_dict = {}

    for article, params in parser_dict.items():
        if 'includes' in params:
            include_files = params.pop('includes')
            for include_file in include_files:
                include_dict = _include_groups(include_file)
                resulted_dict.update(include_dict)

    resulted_dict[article] = parser_dict[article]
    return resulted_dict

