    """
    Returning dict with options which deprecate others.

    : returns: dict with the following format:
        {
            "option_in_question": {
                "deprecated_in_version": str, "to_be_removed_in_version": str, "client_option": str
            },
            "another_option_in_question": {
                "deprecated_in_version": str, "to_be_removed_in_version": str, "client_option": str
            }
        }
        """

    deprecated_args = {}

    for option in self.parameter_dict:
        if "deprecated" in self.parameter_dict[option]:
            client_option = self.parameter_dict[option].get("client_option")
            if client_option is not None:
                deprecated_in_version = self.parameter_dict[option]["deprecated_in_version"]
                to_be_removed_in_version = self.parameter_dict[option].get("to_be_removed_in_version",
                                                                           deprecated_in_version)
                deprecated_args[option] = {
                    "deprecated_in_version": deprecated_in_version,
                    "to_be_removed_in_version": to_be_removed_in_version,
                    "client_option": client_option
                }

    return deprecated_args

