def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    cond_required_args = []
    for arg_name, spec in options_spec.items():
        if "required_when" in spec:
            if spec["required_when"].startswith("!"):
                negation = True
                condition = spec["required_when"][1:]
            else:
                negation = False
                condition = spec["required_when"]
            if args is None or arg_name not in args:
                continue
            command, cond_arg_name = condition.split(".")
            if command == command_name:
                if negation:
                    if cond_arg_name not in args:
                        cond_required_args.append(arg_name)
                else:
                    if cond_arg_name in args:
                        cond_required_args.append(arg_name)
    return cond_required_args

