def create_complex_argumet_type(subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Validate parameters
    if not isinstance(subcommand, str):
        raise TypeError("subcommand must be a string, got {}".format(type(subcommand)))
    if not isinstance(type_name, str):
        raise TypeError("type_name must be a string, got {}".format(type(type_name)))
    if not isinstance(option_name, str):
        raise TypeError("option_name must be a string, got {}".format(type(option_name)))
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dict, got {}".format(type(spec_option)))

    # Build the complex type instance
    complex_type = self.get_complex_type(type_name, spec_option.get("__type__", {}))
    return complex_type(**spec_option.get("__args__", []))

