def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("'vars_dict' must be a dictionary")
    if extra_vars and not isinstance(extra_vars, list):
        raise TypeError("'extra_vars' must be a list")
    if extra_vars:
        for var in extra_vars:
            if isinstance(var, dict):
                vars_dict.update(var)
            else:
                vars_dict[str(var)] = var

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """

    if extra_vars is None:
        return vars_dict

    else:
        for extra_var in extra_vars:
            key = list(extra_var)[0]
            value = extra_var[key]
            if key not in vars_dict:
                vars_dict[key] = value
            else:
                vars_dict[key].append(value)

        return vars_dict

