    """Extend ``vars_dict`` with ``extra-vars``

    Args:
        vars_dict (dict): Dictionary to merge extra-vars into
        extra_vars (list, optional): List of extra-vars

    Returns:
        dict: Extended ``vars_dict``
    """
    if not vars_dict:
        return vars_dict

    elif not extra_vars:
        return vars_dict

    else:
        return ensure_mapping_format(extend_variables(vars_dict, extra_vars))

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra_vars``

    Args:
        vars_dict (dict): Dictionary to merge extra-vars into
        extra_vars (list): List of extra-vars

    Returns:
        dict: Updated ``vars_dict`` with ``extra_vars`` merged in

    Examples:
        >>> vars_dict = {'a': 'b', 'c': 'd'}
        >>> extra_vars = [{'foo': 'bar'}, {'baz': 'foobar'}]
        >>> merge_extra_vars(vars_dict, extra_vars)
            {'a': 'b', 'c': 'd', 'foo': 'bar', 'baz': 'foobar'}
    """
    # Check if vars_dict is not None and is a dictionary
    if vars_dict is None or not isinstance(vars_dict, dict):
        raise ValueError("Variable 'vars_dict' should be a non-empty dictionary")

    # Check if extra_vars is a list
    if extra_vars is not None and not isinstance(extra_vars, list):
        raise ValueError("Variable 'extra_vars' should be a list")

    # Update vars_dict with extra_vars
    if extra_vars:
        for extra_var in extra_vars:
            if not isinstance(extra_var, dict):
                raise ValueError("Variable 'extra_var' should be a dictionary")
            vars_dict.update(extra_var)

    return vars_dict

