def _convert_non_cli_args(parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    cli_name_length = 100
    parser_funcs = dict(
        main=lambda arg: arg,
        virsh=lambda arg: arg if isinstance(arg, list) else arg.split(" "),
        ospd=lambda arg: {
            "host": arg.split(">")[1],
            "data": arg.split(">")[0],
        },
    )
    parser_func = parser_funcs.get(parser_name)
    if parser_func is None:
        return values_dict
    return {key: parser_func(value) for key, value in values_dict.items()}

def _convert_non_cli_args(parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    parser = self.parsers[parser_name]
    for opt in parser.options:
        if opt.property:
            if opt.property in values_dict and values_dict[opt.property] is not None:
                values_dict[opt.property] = opt.convert(values_dict[opt.property])
            elif opt.default is not None:
                values_dict[opt.property] = opt.default
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = toml.load(plugin_dir / "plugin.toml")
    plugin_dict = {f"{plugin_spec['name']}", "=", f"{plugin_spec['version']}"}
    for prop in plugin_spec['info']:
        if isinstance(prop, str):
            plugin_dict[prop] = plugin_spec['info'][prop]
        elif isinstance(prop, dict):
            for k, v in prop.items():
                plugin_dict[k] = v
    return plugin_dict

