def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os

    plugin_spec = os.path.join(plugin_dir, "PLUGIN.spec")
    plugin_data = {}

    with open(plugin_spec, "r") as f:
        for line in f:
            if line.startswith("#") or line.startswith(" ") or line.startswith("\n"):
                continue
            else:
                key, value = line.split("=")
                plugin_data[key.strip()] = value.strip()

    return plugin_data

