def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to to the main entry point.

    :param subparser: the subparser object to extend.
    """

    def _add_subparser(root_subparser, subparser, command_prefix="", **kwargs):
        for name, command in subparser.commands.items():
            command._get_adaptor()
            command._add_extensions(group)
            root_subparser.add_subparsers(prefix=command_prefix)

    for name, subparser in root_subparsers.items():
        if name.startswith("_"):
            continue
        command_prefix = kwargs.get("Command_prefix", "")
        _add_subparser(root_subparsers, subparser, command_prefix=command_prefix)

    for name, subparser in root_subparsers.items():
        if name.startswith("_") or not isinstance(subparser, SubParser):
            continue
        subparser._add_extensions(group)
        root_subparsers.add_subparsers(prefix=command_prefix)

    for name, command in root_subparsers.commands.items():
        wrapper_prefix = "wrap("
        if command_prefix:
            wrapper_prefix += command_prefix + "."
        _add_subparser(root_subparsers, command, prefix=wrapper_prefix + command.name)

